BEGIN;
CREATE TABLE bill_quote (quote_reference text PRIMARY KEY, customer_reference text NOT NULL, source_account_reference text NOT NULL REFERENCES ledger_account(account_reference), payment_type text NOT NULL, notice_code_hash text NOT NULL, creditor_code text NOT NULL, provider_reference text NOT NULL, amount_minor bigint NOT NULL CHECK (amount_minor > 0), fee_minor bigint NOT NULL CHECK (fee_minor >= 0), currency char(3) NOT NULL, status text NOT NULL, expires_at timestamptz NOT NULL, idempotency_key text NOT NULL UNIQUE);
CREATE TABLE bill_payment (payment_reference text PRIMARY KEY, quote_reference text NOT NULL UNIQUE REFERENCES bill_quote(quote_reference), transaction_reference text NOT NULL UNIQUE REFERENCES ledger_journal(journal_reference), provider_transaction_reference text, status text NOT NULL, correlation_id text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE issuer_card (card_reference text PRIMARY KEY, owner_reference text NOT NULL, display_name text NOT NULL, product text NOT NULL, masked_last_four char(4) NOT NULL, status text NOT NULL, ecommerce_enabled boolean NOT NULL, contactless_enabled boolean NOT NULL, cash_withdrawal_enabled boolean NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE wallet_token (token_reference text PRIMARY KEY, card_reference text NOT NULL REFERENCES issuer_card(card_reference), owner_reference text NOT NULL, device_reference text NOT NULL REFERENCES iam_device(device_reference), provider_token_reference text NOT NULL UNIQUE, status text NOT NULL, created_at timestamptz NOT NULL);
INSERT INTO platform_schema_version(version) VALUES (3);
COMMIT;
